package org.rigelengineproton.android;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Generated bytes only: no original EXEs or game assets are used by these tests. */
public final class GameDataImporterTest {
    private static int checks;
    private static int cases;

    private static void check(boolean value) {
        checks++;
        if (!value) {
            throw new AssertionError("Check " + checks + " failed.");
        }
    }

    private static final class Tree implements GameDataImporter.Source {
        final Map<String, List<GameDataImporter.Entry>> dirs = new HashMap<>();
        String broken = "";
        final List<String> opened = new ArrayList<>();

        Tree() {
            dirs.put("root", new ArrayList<>());
        }

        Tree folder(String name) {
            dirs.get("root").add(new GameDataImporter.Entry(name, name, true));
            dirs.put(name, new ArrayList<>());
            return this;
        }

        Tree file(String directory, String name) {
            dirs.get(directory).add(new GameDataImporter.Entry(directory + "/" + name, name, false));
            return this;
        }

        Tree episode(String directory, int episode) {
            return file(directory, "dn" + episode + ".exe")
                    .file(directory, "worldal1.dn" + episode)
                    .file(directory, "solid0.dn" + episode);
        }

        public List<GameDataImporter.Entry> list(String dir) throws IOException {
            if (!dirs.containsKey(dir)) {
                throw new IOException("Missing folder");
            }
            return dirs.get(dir);
        }

        public InputStream open(GameDataImporter.Entry entry) throws IOException {
            opened.add(entry.id);
            if (entry.id.equals(broken)) {
                throw new IOException("Provider lost access");
            }
            return new ByteArrayInputStream(entry.name.contains("empty")
                    ? new byte[0] : new byte[] {1, 2, 3});
        }
    }

    private static String run(Tree tree, File root) throws IOException {
        return GameDataImporter.importTree(tree, "root", root, name -> {});
    }

    private static File root() throws IOException {
        return Files.createTempDirectory("proton-import-test-").toFile();
    }

    private static void cleanup(File root) throws IOException {
        try (java.util.stream.Stream<Path> paths = Files.walk(root.toPath())) {
            for (Path path : (Iterable<Path>) paths.sorted(java.util.Comparator.reverseOrder())::iterator) {
                Files.delete(path);
            }
        }
    }

    private static void failure(Tree tree, File root) throws IOException {
        boolean failed = false;
        try {
            run(tree, root);
        } catch (IOException expected) {
            failed = true;
        }
        check(failed);
    }

    public static void main(String[] args) throws Exception {
        File root = root();
        try {
            Tree mixed = new Tree().episode("root", 1).file("root", "nukem2.cmp")
                    .file("root", "NUKEM2.F4").file("root", "data.duke")
                    .file("root", "../../DN1.EXE").file("root", "notes.txt");
            String found = run(mixed, root);
            check(found.contains("episode 1") && found.contains("Duke Nukem II"));
            check(new File(root, "library/DN1/DN1.EXE").length() == 3);
            check(new File(root, "library/NUKEM2.F4").length() == 3);
            check(mixed.opened.size() == 5);
            check(!new File(root, "library/data.duke").exists());
            cases++;

            Tree split = new Tree().folder("dN1").folder("dn2")
                    .episode("dN1", 1).episode("dN1", 2).episode("dN1", 3)
                    .file("dn2", "NuKeM2.CmP");
            found = run(split, root);
            check(found.contains("episode 1") && found.contains("episode 2")
                    && found.contains("episode 3") && found.contains("Duke Nukem II"));
            cases++;

            found = run(new Tree().episode("root", 2), root);
            check(found.contains("episode 2") && !found.contains("Duke Nukem II"));
            check(!new File(root, "library/NUKEM2.CMP").exists());
            cases++;

            found = run(new Tree().file("root", "nukem2.cmp"), root);
            check(found.equals("Duke Nukem II"));
            cases++;

            byte[] before = Files.readAllBytes(new File(root, "library/NUKEM2.CMP").toPath());
            failure(new Tree().file("root", "readme.txt"), root);
            check(Arrays.equals(before, Files.readAllBytes(new File(root, "library/NUKEM2.CMP").toPath())));
            cases++;

            Tree duplicate = new Tree().folder("DN2")
                    .file("root", "NUKEM2.CMP").file("DN2", "nukem2.cmp");
            failure(duplicate, root);
            check(new File(root, "library/NUKEM2.CMP").length() == 3);
            cases++;

            Tree broken = new Tree().episode("root", 1);
            broken.broken = "root/solid0.dn1";
            failure(broken, root);
            check(new File(root, "library/NUKEM2.CMP").length() == 3);
            check(!new File(root, "pending").exists());
            cases++;

            Tree empty = new Tree().file("root", "NUKEM2.CMP").file("root", "empty.dn1");
            failure(empty, root);
            check(new File(root, "library/NUKEM2.CMP").length() == 3);
            cases++;

            Thread.currentThread().interrupt();
            try {
                failure(new Tree().episode("root", 1), root);
            } finally {
                Thread.interrupted();
            }
            check(new File(root, "library/NUKEM2.CMP").length() == 3);
            cases++;

            File recovered = root();
            try {
                File previous = new File(recovered, "previous");
                check(previous.mkdir());
                Files.write(new File(previous, "NUKEM2.CMP").toPath(), new byte[] {1});
                check(GameDataImporter.recover(recovered).equals(new File(recovered, "library")));
                check(new File(recovered, "library/NUKEM2.CMP").length() == 1);
            } finally {
                cleanup(recovered);
            }
            cases++;
        } finally {
            cleanup(root);
        }
        System.out.println("Android import tests passed: " + checks + " checks / " + cases + " cases.");
    }
}
